-- The day the client disputed a sent invoice (null when never): from then it earns no interest, is not
-- overdue and takes no payments until the dispute is resolved.
ALTER TABLE invoice ADD COLUMN disputed_on DATE;
-- The day the dispute was resolved (null while it is open or when there was none): interest runs again from it.
ALTER TABLE invoice ADD COLUMN dispute_resolved_on DATE;
-- Whether the line is in the invoice's dispute (from the invoice's disputed_on until it is resolved): only the
-- disputed lines then earn no interest and are not overdue. An open dispute with no line in it covers the whole invoice.
ALTER TABLE invoice_line ADD COLUMN disputed BOOLEAN NOT NULL DEFAULT FALSE;
-- A credit note is an invoice crediting another (credit_of, the original's id); once issued its grand
-- total is kept in credit_total and comes off what the original has due.
ALTER TABLE invoice ADD COLUMN credit_of BIGINT;
ALTER TABLE invoice ADD COLUMN credit_total DECIMAL(19, 2);
-- A credit note may be for more than its original still owes. What the original took of it is kept in
-- credit_applied (credit_retention of that cleared retention it held back); the rest is held on the
-- client's account as a payment naming the credit note (credit_note), which cannot be reversed.
ALTER TABLE invoice ADD COLUMN credit_applied DECIMAL(19, 2);
ALTER TABLE invoice ADD COLUMN credit_retention DECIMAL(19, 2) DEFAULT 0 NOT NULL;
UPDATE invoice SET credit_applied = credit_total WHERE credit_total IS NOT NULL;
ALTER TABLE payment ADD COLUMN credit_note BIGINT;
-- The id of the invoice line a credit note's line credits; NULL for a line that credits no line in particular.
ALTER TABLE invoice_line ADD COLUMN credit_of_line BIGINT;
